security_attr_names := {"protocol", "scheme", "transport", "ssl", "tls", "https", "secure", "encrypted", "encryption", "verify_ssl", "validate_certificate", "check_cert", "https_only", "enforce_https", "secure_transport", "require_tls", "min_tls_version", "ssl_required", "redirect_http_to_https", "force_ssl", "secure_transfer", "encryption_in_transit", "allow_insecure_connections", "insecure_skip_verify", "verify_peer_certificate"}

# Check if value is an insecure protocol string
is_insecure_protocol(value) {
    value.ir_type == "String"
    lower(value.value) == insecure_protocols[_]
}

# Check if value is an insecure port
is_insecure_port(value) {
    value.ir_type == "String"
    value.value == insecure_ports[_]
