# Check if value indicates disabled/negated security
is_security_disabled(value) {
    value.ir_type == "String"
    lower(value.value) == negation_keywords[_]
}

# Check if value is boolean false (disabled security)
is_security_disabled(value) {
    value.ir_type == "Boolean"
    value.value == false
}

# Check if string contains insecure protocol prefix
has_insecure_url_prefix(value) {
    value.ir_type == "String"
    startswith(lower(value.value), "http://")
}

has_insecure_url_prefix(value) {
    value.ir_type == "String"
    startswith(lower(value.value), "ftp://")
}

# Recursively check Hash value for insecure configurations
check_hash_for_insecurity(hash) {
    hash.ir_type == "Hash"
    some key, val
    hash.value[key] = val
    _check_value_for_insecurity(val)
}

# Recursively check Array value for insecure configurations
check_array_for_insecurity(arr) {
    arr.ir_type == "Array"
    some i
    _check_value_for_insecurity(arr.value[i])
}

# Internal helper to check any value type for insecurity
_check_value_for_insecurity(val) {
    is_insecure_protocol(val)
}

_check_value_for_insecurity(val) {
    is_insecure_port(val)
}

_check_value_for_insecurity(val) {
    has_insecure_url_prefix(val)
}

_check_value_for_insecurity(val) {
    is_security_disabled(val)
}

_check_value_for_insecurity(val) {
    check_hash_for_insecurity(val)
}

_check_value_for_insecurity(val) {
    check_array_for_insecurity(val)
}

# Check if attribute name indicates security-related setting
is_security_attribute(name) {
    lower(name) == security_attr_names[_]
}

# Check attribute for cleartext transmission weakness
attr_indicates_cleartransmission(attr) {
    # Direct insecure protocol value
    is_insecure_protocol(attr.value)
}

attr_indicates_cleartransmission(attr) {
    # Insecure URL in value
    has_insecure_url_prefix(attr.value)
}

attr_indicates_cleartransmission(attr) {
    # Insecure port specification
    is_insecure_port(attr.value)
}

attr_indicates_cleartransmission(attr) {
    # Security attribute with disabled value
    is_security_attribute(attr.name)
    is_security_disabled(attr.value)
}

attr_indicates_cleartransmission(attr) {
    # Nested Hash with insecure configuration
    attr.value.ir_type == "Hash"
    check_hash_for_insecurity(attr.value)
}

attr_indicates_cleartransmission(attr) {
    # Nested Array with insecure configuration
    attr.value.ir_type == "Array"
    check_array_for_insecurity(attr.value)
}

# Main rule: Detect cleartext transmission of sensitive information (CWE-319)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr_indicates_cleartransmission(attr)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Data transmission channels must use encryption-in-transit to prevent eavesdropping. (CWE-319)"
    }
}

