package glitch

import data.glitch_lib

# Insecure protocol strings (case-insensitive)
insecure_protocols := {"http", "ftp", "telnet", "smtp", "pop3", "imap", "ldap"}

# Insecure port numbers (common unencrypted defaults)
insecure_ports := {21, 23, 25, 80, 110, 143, 389, 445, 3306, 5432, 587, 8080}
insecure_ports_str := {"21", "23", "25", "80", "110", "143", "389", "445", "3306", "5432", "587", "8080"}

# Negation keywords indicating disabled security
negation_keywords := {"disable", "disabled", "false", "off", "none", "no", "unencrypted", "plaintext", "insecure", "unsafe", "cleartext", "raw", "unprotected"}

# Security-related attribute names for encryption in transit
security_attr_names := {"validate_certs", "verify_ssl", "ssl", "tls", "https", "secure", "encrypted", "encryption", "insecure_skip_verify", "allow_insecure", "enforce_https", "require_tls", "force_ssl", "protocol", "scheme"}

# Weak TLS versions
weak_tls_versions := {"sslv3", "tlsv1", "tlsv1.0", "tlsv1.1", "1.0", "1.1"}

# Check if string value equals insecure protocol (exact match)
is_insecure_protocol_exact(value) {
    value.ir_type == "String"
    lower(value.value) == insecure_protocols[_]
}

# Check if string starts with insecure URL prefix
has_insecure_url_prefix(value) {
    value.ir_type == "String"
    startswith(lower(value.value), "http://")
}

has_insecure_url_prefix(value) {
    value.ir_type == "String"
    startswith(lower(value.value), "ftp://")
}

# Check if string contains insecure protocol at start after interpolation
contains_insecure_protocol_in_string(value) {
    value.ir_type == "String"
    lower_val := lower(value.value)
    startswith(lower_val, "http://")
}

contains_insecure_protocol_in_string(value) {
    value.ir_type == "String"
    lower_val := lower(value.value)
    startswith(lower_val, "ftp://")
}

# Check if value is an insecure port
is_insecure_port(value) {
    value.ir_type == "String"
    value.value == insecure_ports_str[_]
}

is_insecure_port(value) {
    value.ir_type == "Integer"
    value.value == insecure_ports[_]
}

# Check if value indicates disabled/negated security
is_security_disabled(value) {
    value.ir_type == "String"
    lower(value.value) == negation_keywords[_]
}

is_security_disabled(value) {
    value.ir_type == "Boolean"
    value.value == false
}

# Check if attribute name is security-related
is_security_attribute(name) {
    lower(name) == security_attr_names[_]
}

# Check if attribute name indicates certificate/SSL validation
is_cert_validation_attribute(name) {
    lower(name) == {"validate_certs", "verify_ssl", "ssl_verify", "verify_peer", "check_certificate"}
}

# Check if value indicates weak TLS version
is_weak_tls_version(value) {
    value.ir_type == "String"
    lower(value.value) == weak_tls_versions[_]
}

# Recursively check if an expression contains insecure protocol patterns
expr_contains_insecure(expr) {
    expr.ir_type == "String"
    has_insecure_url_prefix(expr)
}

expr_contains_insecure(expr) {
    expr.ir_type == "Sum"
    expr_contains_insecure(expr.left)
}

expr_contains_insecure(expr) {
    expr.ir_type == "Sum"
    expr_contains_insecure(expr.right)
}

expr_contains_insecure(expr) {
    expr.ir_type == "Sum"
    walk_sum_parts(expr, part)
    has_insecure_url_prefix(part)
}

# Walk through Sum to find String parts with insecure prefixes
walk_sum_parts(sum_expr, part) {
    sum_expr.ir_type == "Sum"
    walk_sum_parts(sum_expr.left, part)
}

walk_sum_parts(sum_expr, part) {
    sum_expr.ir_type == "Sum"
    walk_sum_parts(sum_expr.right, part)
}

walk_sum_parts(sum_expr, sum_expr) {
    sum_expr.ir_type == "String"
}

# Recursively check Hash values for insecure content
hash_contains_insecure(hash) {
    hash.ir_type == "Hash"
    some item
    item = hash.value[_]
    expr_contains_insecure(item.value)
}

hash_contains_insecure(hash) {
    hash.ir_type == "Hash"
    some item
    item = hash.value[_]
    is_insecure_protocol_exact(item.value)
}

hash_contains_insecure(hash) {
    hash.ir_type == "Hash"
    some item
    item = hash.value[_]
    is_security_disabled(item.value)
}

hash_contains_insecure(hash) {
    hash.ir_type == "Hash"
    some item
    item = hash.value[_]
    is_insecure_port(item.value)
}

hash_contains_insecure(hash) {
    hash.ir_type == "Hash"
    some item
    item = hash.value[_]
    is_weak_tls_version(item.value)
}

# Recursively check Array values for insecure content
array_contains_insecure(arr) {
    arr.ir_type == "Array"
    some i
    expr_contains_insecure(arr.value[i])
}

array_contains_insecure(arr) {
    arr.ir_type == "Array"
    some i
    is_insecure_protocol_exact(arr.value[i])
}

array_contains_insecure(arr) {
    arr.ir_type == "Array"
    some i
    is_security_disabled(arr.value[i])
}

array_contains_insecure(arr) {
    arr.ir_type == "Array"
    some i
    is_insecure_port(arr.value[i])
}

# Check if attribute value contains insecure patterns
attr_value_insecure(attr) {
    expr_contains_insecure(attr.value)
}

attr_value_insecure(attr) {
    is_insecure_protocol_exact(attr.value)
}

attr_value_insecure(attr) {
    has_insecure_url_prefix(attr.value)
}

attr_value_insecure(attr) {
    is_insecure_port(attr.value)
}

attr_value_insecure(attr) {
    is_security_disabled(attr.value)
}

attr_value_insecure(attr) {
    is_weak_tls_version(attr.value)
}

attr_value_insecure(attr) {
    hash_contains_insecure(attr.value)
}

attr_value_insecure(attr) {
    array_contains_insecure(attr.value)
}

# Check if attribute indicates cleartext transmission
attr_indicates_cleartransmission(attr) {
    is_security_attribute(attr.name)
    attr_value_insecure(attr)
}

# Specifically for certificate validation being disabled
attr_indicates_cleartransmission(attr) {
    is_cert_validation_attribute(attr.name)
    is_security_disabled(attr.value)
}

# Protocol set to insecure value
attr_indicates_cleartransmission(attr) {
    lower(attr.name) == "protocol"
    is_insecure_protocol_exact(attr.value)
}

# URL/scheme attributes with insecure protocols
attr_indicates_cleartransmission(attr) {
    lower(attr.name) == "url"
    expr_contains_insecure(attr.value)
}

attr_indicates_cleartransmission(attr) {
    lower(attr.name) == "source"
    expr_contains_insecure(attr.value)
}

# Check variables for insecure patterns
variable_indicates_cleartransmission(var) {
    is_security_attribute(var.name)
    attr_value_insecure(var)
}

variable_indicates_cleartransmission(var) {
    lower(var.name) == "url"
    expr_contains_insecure(var.value)
}

variable_indicates_cleartransmission(var) {
    lower(var.name) == "grafana_url"
    expr_contains_insecure(var.value)
}

variable_indicates_cleartransmission(var) {
    var.value.ir_type == "Hash"
    some item
    item = var.value.value[_]
    lower(item.key.value) == "protocol"
    is_insecure_protocol_exact(item.value)
}

# Main rule for atomic units
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr_indicates_cleartransmission(attr)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Data transmission channels must use encryption-in-transit to prevent eavesdropping. (CWE-319)"
    }
}

# Rule for variables at unit block level
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    variable_indicates_cleartransmission(var)

    result := {
        "type": "sec_https",
        "element": var,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Data transmission channels must use encryption-in-transit to prevent eavesdropping. (CWE-319)"
    }
}

